Here are concise, safe patterns across common stacks:

- PostgreSQL (Node.js, node-postgres)
  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: process.env.DATABASE_URL });

  async function getUserByEmail(email) {
    const res = await pool.query(
      'SELECT id, email, created_at FROM users WHERE email = $1',
      [email]
    );
    return res.rows[0] || null;
  }

- MySQL (Node.js, mysql2)
  const mysql = require('mysql2/promise');
  const conn = await mysql.createConnection({ uri: process.env.DSN });
  const [rows] = await conn.execute(
    'SELECT id, name FROM customers WHERE id = ?',
    [customerId]
  );

- PostgreSQL (Python, psycopg)
  import psycopg
  with psycopg.connect(conninfo) as conn:
      with conn.cursor() as cur:
          cur.execute(
              "INSERT INTO logs(level, message) VALUES (%s, %s) RETURNING id",
              (level, message)
          )
          new_id = cur.fetchone()[0]

- MySQL (Python, mysqlclient or mysql-connector)
  cursor.execute(
      "UPDATE users SET last_login = %s WHERE id = %s",
      (last_login, user_id)
  )

